export function SocialProof({
  statText = "{{statText}}",
  style = "{{style}}",
  accent = "{{accent}}",
  showStat = {{showStat}},
}) {
  const stars = style === "stars";
  return (
    <div style={{ font: "15px system-ui, sans-serif", color: "#241430", padding: 20, textAlign: "center" }}>
      {showStat && <p style={{ margin: "0 0 14px", fontWeight: 700, fontSize: 14, color: "#241430aa" }}>{statText}</p>}
      {!stars && (
        <div style={{ display: "flex", gap: 18, justifyContent: "center", fontWeight: 700, color: "#24143066" }}>
          <span>Nimbus</span><span>Fenwick</span><span>Cobalt</span>
        </div>
      )}
      {stars && (
        <div aria-label="Rated 4.9 out of 5" style={{ marginTop: 8, fontSize: 16, letterSpacing: 2, color: accent }}>
          &#9733;&#9733;&#9733;&#9733;&#9733; <span style={{ fontSize: 13, letterSpacing: 0, color: "#241430aa", marginLeft: 6 }}>4.9/5</span>
        </div>
      )}
    </div>
  );
}
